import React from 'react';
import {createRoot} from 'react-dom/client';
import {MemoryRouter,Routes,Route} from 'react-router-dom';
import '../../src/index.css';
import '../../src/pages/customers/customers.css';
import AdminLayout from '../../src/layouts/AdminLayout';
import Wishlists from '../../src/pages/wishlist/WishlistAnalyticsPage';
import Before from './wishlists-before';
import {useAuthStore} from '../../src/store/authStore';
useAuthStore.setState({user:{id:'fixture-admin',name:'Test Admin',role:'ADMIN'} as any,status:'authenticated',isAuthenticated:true,loading:false});
const q=new URLSearchParams(location.search),Page=q.has('before')?Before:Wishlists;
createRoot(document.getElementById('root')!).render(<MemoryRouter initialEntries={['/admin/wishlists']}><Routes><Route path="/admin" element={<AdminLayout/>}><Route path="wishlists" element={q.has('customers')?<div className="fy-customers">Customer sidebar style check</div>:<Page/>}/></Route></Routes></MemoryRouter>);
